"""Register a reviewable temporal-analysis design; read metadata/rain context only.
No hydraulic, routing, traffic optimization or population-impact computation.
"""
from pathlib import Path
import os,sys,json,datetime as dt,hashlib,html
os.environ.setdefault('OPENBLAS_NUM_THREADS','1')
import numpy as np,pandas as pd
from scipy.sparse import load_npz
ROOT=Path(__file__).resolve().parents[2];D=ROOT/'data/processed';OUT=ROOT/'data/exp/research-design/three_ward_five_event_temporal_plan_v1'
OLD=D/'three_ward_cross_event_protection_v1';NEW=D/'three_ward_five_event_population_validation_v1';OLDR=ROOT/'data/exp/estimation'/OLD.name;NEWR=ROOT/'data/exp/estimation'/NEW.name
UTC=dt.timezone.utc;JST=dt.timezone(dt.timedelta(hours=9))
def sha(p):
 h=hashlib.sha256()
 with p.open('rb')as f:
  for b in iter(lambda:f.read(8*1024*1024),b''):h.update(b)
 return h.hexdigest()
def dump(p,x):p.write_text(json.dumps(x,ensure_ascii=False,indent=2,allow_nan=False,default=lambda z:z.item()if isinstance(z,np.generic)else str(z))+'\n')
def table(x):return pd.DataFrame(x).to_html(index=False,escape=True,na_rep='—',float_format=lambda v:f'{v:,.3f}')
def main():
 OUT.mkdir(parents=True,exist_ok=True);assert not(OUT/'protocol.json').exists(),'Preserve registered plan; version revisions separately'
 inventory=[];binding={};events={};allruns=[]
 for p,r in [(OLD,OLDR),(NEW,NEWR)]:
  m=json.loads((p/'run_manifest.json').read_text());binding[str((p/'run_manifest.json').relative_to(ROOT))]=sha(p/'run_manifest.json')
  selected=[x for x in m['runs']if x['arm']=='U']
  for run in selected:
   case=run['case_id'];audit=r/'execution'/case/'audit.json';a=json.loads(audit.read_text());assert a['all_checks_passed']and a['admission']['technical_reference'];clock=p/'execution'/(case+'_output_clock.npz');t=np.load(clock)['Actual Map Time'];assert len(t)==109 and np.max(abs(t-np.arange(109)*300))<=.001;model=ROOT/run['folder']/'sfincs_map.nc';assert model.exists();allruns.append(run)
   for f in [audit,clock,model]:binding[str(f.relative_to(ROOT))]=sha(f)
   inventory.append(dict(case_id=case,event_id=run['event_id'],parent_id=run['parent_id'],geometry='U',stage=run['stage'],map_frames=109,nominal_spacing_s=300,actual_start_s=float(t[0]),actual_end_s=float(t[-1]),max_nominal_actual_difference_s=float(np.max(abs(t-np.arange(109)*300))),map_bytes=model.stat().st_size,map_path=str(model.relative_to(ROOT)),clock_path=str(clock.relative_to(ROOT)),audit_path=str(audit.relative_to(ROOT)),numerical_admission=True,ground_reference='conditional_admitted_support;not_independent_truth'))
  es=json.loads((p/'event_selection.json').read_text())['events']
  for e in es:events[e['event_id']]=e
 assert len(inventory)==10 and len(events)==5 and len({r['parent_id']for r in allruns})==5
 rainmatrix=D/'tokyo_historical_radar_20240821_v1/terrain_source_area_matrix.npz';area=np.asarray(load_npz(rainmatrix).sum(0)).ravel();used=area>0;binding[str(rainmatrix.relative_to(ROOT))]=sha(rainmatrix);rainrows=[]
 for eid,e in sorted(events.items()):
  folder=OLD/'rainfall'/eid if eid in ['E20240830','E20250911']else NEW/'rainfall'/eid;f=folder/'radar_intervals.npz';binding[str(f.relative_to(ROOT))]=sha(f);rad=np.load(f);rate=rad['representative_intensity_mm_h'].reshape(108,-1)[:,used].astype(float)@area[used]/area.sum();roll=np.convolve(rate/12,np.ones(12),'valid');end_index=int(np.argmax(roll))+12;start=dt.datetime.fromisoformat(e['window_start_jst']);total=float(rate.sum()/12);rainrows.append(dict(event_id=eid,parent_id=e['parent_id'],window_start_jst=e['window_start_jst'],window_end_jst=e['window_end_jst'],rain_9h_mm=total,rain_by4h_fraction=float(rate[:48].sum()/rate.sum()),rain_by4h_percent=float(rate[:48].sum()/rate.sum()*100),rolling60_peak_end_elapsed_s=end_index*300,rolling60_peak_end_jst=(start+dt.timedelta(seconds=end_index*300)).isoformat(),rolling60_peak_mm=float(roll.max()),excluded_antecedent_rain_mm=float(e.get('rain_before_window_reconstructed_mm',e.get('rain_before_window_mm',0)))))
 print('Ten qualified hydraulic cases and five rain clocks inspected',flush=True)
 deps=[NEW/'motor_common_support.npz',D/'three_ward_motor_flood_access_v1/road_projection.npz',D/'three_ward_motor_flood_access_v1/road_inventory.csv',D/'three_ward_normal_vehicle_repair_v1/turn_router.npz',D/'three_ward_normal_vehicle_repair_v1/multi_endpoint_components.npz',D/'three_ward_normal_vehicle_repair_v1/multi_network_endpoints.csv',D/'three_ward_normal_vehicle_repair_v1/multi_routing_demands.npz',D/'three_ward_demand_protection_feedback_v1/protection_masks.npz',D/'three_ward_demand_protection_feedback_v1/capacity_assumptions.npz',D/'three_ward_normal_vehicle_choice_v1/choice_costs.npz',D/'three_ward_night_population_transport_v1/block_access_support.npz',D/'three_ward_night_population_transport_v1/protocol.json',D/'three_ward_population_block_stability_v1/official_2020_block_count_baseline.csv',D/'three_ward_population_block_stability_v1/population_input_admission_list.csv',D/'three_ward_population_block_stability_v1/block_population_intervals.npz',D/'three_ward_normal_transport_network_v1/surface_physical_edges.jsonl.gz',D/'plateau_water/central_three_ward_boundaries.geojson',NEWR/'population/validation.json',NEWR/'traffic/validation.json']
 for f in deps:binding[str(f.relative_to(ROOT))]=sha(f)
 protocol={
 'plan_id':OUT.name,'decision':'MILI-D-20261018-014','status':'design_only_not_executed','created_utc':dt.datetime.now(UTC).isoformat(),
 'question':'When,where and for how long does modeled road impassability impair resident-stock vehicle access across five rainfall events,and when do fixed protection,demand management and ideal guidance improve matched outcomes?',
 'scope':{'rainfall_parents':5,'hydraulic_cases':10,'geometry':'Frozen U urban-information bundle only;no new T/U comparison','stages':['L','H'],'stored_map_frames_per_case':109,'nominal_step_s':300,'horizon_s':32400,'new_hydraulic_runs':0,'training':False,'sealed_test_access':False,'geography':'Whole Chiyoda,Chuo,Minato with unchanged10km routing context and16boundary portals'},
 'time':{'source':'Actual Map Time,not rounded raw NetCDF nominal labels','alignment_tolerance_s':.001,'analysis_interval':'0..32400s;retain raw actual times and explicitly intersect the final slightly overshooting interval with the9h window','rain_clock':'JST and trueUTC recorded for every event;storm-relative times are not common historical clock times','no_peak_mosaic':'Online non-simultaneous peak envelopes never define simultaneous closures,routes,population or representative snapshots','right_censoring':'Roads still restricted at9h are not claimed recovered;onset at0is left-censored'},
 'fixed_inputs':{'quality':'Reuse the final common ground/road admission and exact prior numerical policy;no relaxed masks or reselection','roads':'Same motor permissions,one-way,turn history,native bridge/tunnel levels;only qualified ground receives DEM-derived depth','thresholds_m':{'slow':.1,'closed':.3},'slow_rule':'0.1<=depth<0.3:reference time2x,capacity0.5x;depth>=0.3:source edge closed as a hypothesis','unknown':'Keep height/coverage/permission unknowns explicit. Main hazard branch assumes unknown-exposure roads available;unknown-withheld is a separately paired evidence stress,not a physical upper bound. Walk-only supplementation never becomes vehicle access.','protection':'Original118source roads,4743.231745m,ideal dry passability;not reselected using population,time or new outcomes','population':'Official2020resident stock496345,frozen0/10/25m candidate-access support and original building-allocation sidecars;no centroid or equal-node population assignment','traffic':'Same high17h PT-derived driver proxy,capacity assumptions,two-route UE/SO objectives and numerical gates;not event-specific observed traffic or dynamic queues'},
 'road_accounting':{'unit':'Frozen unique physical source edge;collapse directed duplicates for length accounting','clip':'Clip projected source centerline geometry to official ward polygons;three-ward total uses union-clipped geometry,not whole length of any intersecting edge. Retain original whole-source closure hypothesis.','shared_boundary':'Assign positive-length coincident administrative-boundary fragments once using a deterministic ward-code tie rule;sum ward lengths must equal union length within1mm','denominators':'Qualified open/slow/closed length partitions qualified physical length at each time;unknown-exposure length reported separately;no treating unsupported links as dry','transitions':'Find sampled0->1 and1->0 runs;onset/recovery bracketed between neighboring actual map times. Do not claim detection of closures shorter than5min or unobserved oscillations.','duration':'Primary road-length-hours uses trapezoidal integration of sampled closed length. Per-road sampled episode duration and onset/end brackets are descriptive;conditional episode bounds assume no hidden reopening between consecutive closed samples. Left/right hold integrals are discretization sensitivities,not guaranteed physical bounds.'},
 'population_contract':{'instantaneous':'For fixed normal-supported candidate set N_b,population P_b and loss indicator s_n(t):L_b(t)=P_b*min_n s_n(t),U_b(t)=P_b*max_n s_n(t). Normal-mixed/missing blocks are held,never counted as known storm loss.','main_buffer_m':10,'sensitivity_buffers_m':[0,25],'depth':'Retain lower/upper depth states separately;their outer envelope is conditional on the fixed road/terrain interpretation. Buffer variants are different access assumptions,not probability samples.','peak':'Report [max_t sum_b L_b(t),max_t sum_b U_b(t)] with separate endpoint times;do not sum per-block maxima and call it one simultaneous peak.','ever':'Secondary fixed-residence-stock analysis:first OR the loss indicator across time at each candidate,then take block min/max and sum once. This assumes one unchanged candidate location per resident;not observed unique travelers or actual stranded persons.','benefit':'Compute paired candidate-state differences at the SAME time with the SAME normal support. Do not subtract aggregate interval endpoints and claim a guaranteed number of people saved.','identity':'All496345residents partition into eligible conditional inputs or explicit unresolved pools in every state;no vehicle/trip-to-person multiplier. No time-slice population sum.','interpretation':'Vehicle-access loss to any outer portal is not loss of walking/rail alternatives,access to a named service,or actual personal isolation. Daytime occupancy remains a separate future input.'},
 'reference_time_rule':{'registration':'Freeze these rules before computing new road/policy outcomes;do not choose times using intervention benefit.','rain_reference':'For each rainfall parent,earliest endpoint of maximum source-area-weighted rolling60min reconstructed rainfall;use that actual output frame within0.001s.','impact_reference':'For each H/no-protection case,earliest maximum of unique union-clipped qualified closed length at0.3m using lower-depth/unknown-available branch. Zero maximum is explicitly no known closures,not evidence of no flood anywhere.','deduplication':'If the two H anchors coincide,compute once;retain both selection reasons. If distinct,retain both even if one appears favorable/unfavorable. Always flag a peak at horizon as censored.','stage_comparison':'At every time,compare L/H at identical elapsed time. At each H anchor,show L/H road and population states at that same time. Difference of separate event maxima is a difference in peak magnitudes,not an instantaneous stage effect.','initial_snapshot':'Keep prior4h results as labeled context;reuse an optimization only if the COMPLETE traffic input/path/objective fingerprint is identical,not because times or closure counts happen to match.'},
 'measure_matrix':{'first_wave':'Five H events x up to two unique predeclared reference times x2protection states x4deferral fractions x2guidance objectives','protection':['flood','targeted'],'deferral':[0,.1,.2,.3],'guidance':['UE','SO'],'maximum_reference_states':10,'maximum_cells':160,'normal_controls_reused':8,'maximum_candidate_path_sweeps':40,'comparisons':'Protection at same event,time,retained demand and guidance;UE/SO at identical retained demand and path pool;deferral comparisons retain original-request denominator and list removed requests.','fixed_cost_cohort':'Within each event/reference state,the original no-action/no-deferral reachable core OD is frozen for all interventions;mean-cost indices cannot be directly pooled across event-specific cohorts.','unknown_evidence_diagnostic':'At selected H anchors only,retain separately paired unknown-withheld normal and flood accessibility;report lost baseline support. It is not an additional physical flood bound.','multitime_scope':'Snapshot assignments are independent static stress tests;not sequential traffic evolution,real arrival/departure trajectories,queues or cumulative daily completed trips.'},
 'execution_stages':[{'id':'A0','task':'Verify hashes,clocks,case lineage,source geometry and projected clipping on whole-area inputs;time up to8representative routing states','success':'All10cases qualified,109actual frames each,no duplicated lengths,old snapshots reproduced exactly when the same length definition is used','budget_active_s':600},{'id':'A1','task':'Extract all1090simultaneous road states and resident-stock access trajectories;prepare episode/peak/ever summaries and reference-state manifest','success':'Every state accounted,population conserved,unresolved explicit,no peak mosaics or time-slice sums','budget_active_s':14400},{'id':'A2','task':'Deduplicate selected H anchors and execute bounded matched measures;reuse only fingerprint-identical fits and8normal controls','success':'At most160cells,original OD ledger and optimizer gates preserved;matched evidence for allfive rain parents','budget_active_s':21600}],
 'budget':{'workers':1,'target_memory_gib':8,'maximum_new_products_gib':15,'maximum_new_hydraulics':0,'maximum_primary_reachability_graph_states':4360,'note':'Upper-bound proposal,not an executed allocation. Hash-cache identical graph states;store packed road/block states and aggregates instead of duplicated long tables or full node distances at every time. Benchmark before estimating completion time.'},
 'stopping_rules':['Stop on changed bound inputs,failed original numerical admission,missing/incompatible clocks or unsupported map variables.','Hold a failed spatial join,duplicate length account,mask promotion or nonconserved population/OD ledger;never change masks or tolerances to make a result pass.','Original per-path180s,per-fit120s,restricted gap<=0.001,component balance<1e-6 and closed-arc zero remain;preserve failed attempts,no automatic hydraulic restart.','Pause/stop flags and stage resource caps must work before future execution. Heterogeneous or null policy benefits are valid findings and do not trigger case substitution.'],
 'deliverables':['Five-event rainfall,closed-road-length and resident-impact trajectories','Ward maps of closure episodes,longest sampled restriction and unrecovered-at-horizon roads','Resident-stock instantaneous,peak and ever intervals with normal-support gaps','Same-time low/high-stage contrasts','Representative-time manifest and complete reuse/exclusion ledger','Matched protection/deferral/guidance tradeoff panels covering allfiveevents'],
 'interpretation_limits':['Numerical/cross-event consistency is not observed historical flood or congestion accuracy.','Five selected weather dates are event parents,not random population samples;descendants,times,grids and measures are not new independent rain events.','Same dry9h initial condition excludes prior rainfall and may omit full recession;no recovery beyond horizon or full historic reconstruction.','Modern urban geometry and historical2020resident stock are controlled inputs,not historical occupancy.','No claims of fully3D fluid simulation,proven superiority to terrain-only analysis,actual stranded people,validated queue delays or engineering effectiveness.'],
 'status_of_research_contract':'This scoped design does not rewrite the legacy surrogate-oriented AnaSOP sections3-8. Future integration of those sections requires their responsible data,variable,figure/table and estimation workflows;no unrelated rewrite is included here.'}
 metrics=[
 ('closed_length_km','Unique ward-clipped qualified source-road length at depth>=0.3m','km','Each actual frame;lower/upper depth separate'),
 ('slow_length_km','Unique qualified road length with0.1<=depth<0.3m','km','Never counted again as closed'),
 ('unknown_exposure_length_km','Retained road length without qualified surface/deck exposure','km','Separate denominator;not dry'),
 ('closed_length_hours','Trapezoidal integral of sampled closed length over0..9h','km h','Sampled occupancy summary,not guaranteed continuous-duration truth'),
 ('closure_onset_interval','Previous open to first observed closed actual time','s','Left censor if already closed at0'),
 ('recovery_interval','Last observed closed to next observed open actual time','s','Right censor if still closed at9h'),
 ('sampled_longest_episode','Longest sampled contiguous closed run,with onset/recovery brackets','min','Cannot resolve hidden reopenings or sub5min episodes'),
 ('instant_resident_loss_interval','Sum of block candidate-location lower/upper loss at a common time','resident stock','2020night baseline;unresolved excluded and separately counted'),
 ('peak_resident_loss_interval','Max over time of simultaneous total endpoints','resident stock','Endpoint times may differ;not sum of block peaks'),
 ('ever_resident_loss_interval','Candidate-wise temporal OR then block min/max and population sum','resident stock','Fixed residence-location assumption;not actual stranded-person count'),
 ('normal_support_unresolved','Census residents in missing/mixed normal access support','resident stock','Retain in total budget;never impute as storm loss'),
 ('paired_restored_stock_interval','Block envelope of same-candidate no-action minus action loss','resident stock','Cannot infer guaranteed benefit from marginal interval subtraction'),
 ('original_request_completion','Retained served proxy divided by original fixed core request','fraction','Deferred requests remain noncompleted,not restored'),
 ('deferred_original_request','Requests removed from current modeled hour','vehicle-trip proxy','No assumption of later completion or person conversion'),
 ('fixed_cohort_model_cost_index','Cost on frozen original no-action-reachable core OD;baseline100','index','Within event/reference cohort;not actual delay minutes'),
 ('same_retained_SO_UE_cost_ratio','Total modeled network costSO/UE on identical retained demand','ratio','Restricted two-route ideal guidance,not all-person welfare')]
 outputs=[dict(metric=m,definition=d,unit=u,interpretation=q)for m,d,u,q in metrics]
 pd.DataFrame(inventory).sort_values('case_id').to_csv(OUT/'input_inventory.csv',index=False,encoding='utf-8-sig');pd.DataFrame(rainrows).to_csv(OUT/'rain_timing_context.csv',index=False,encoding='utf-8-sig');pd.DataFrame(outputs).to_csv(OUT/'metric_dictionary.csv',index=False,encoding='utf-8-sig')
 matrix=[]
 for eid in sorted(events):
  for anchor in ['rain_rolling60_peak_end','H_noaction_closed_length_peak']:
   matrix.append(dict(event=eid,stage='H',time_rule=anchor,protection_states=2,deferral_states=4,guidance_states=2,maximum_cells=16,status='rule_registered_time_not_yet_selected',select_using_policy_benefit=False))
 pd.DataFrame(matrix).to_csv(OUT/'comparison_matrix.csv',index=False,encoding='utf-8-sig');dump(OUT/'protocol.json',protocol);dump(OUT/'source_bindings.json',dict(sha256=binding,plan_generator_sha256=sha(Path(__file__))))
 timing=pd.DataFrame(rainrows);view=timing[['event_id','rain_9h_mm','rain_by4h_percent','rolling60_peak_end_jst','excluded_antecedent_rain_mm']].copy();view.columns=['降雨','9小时重建雨量(mm)','前4小时雨量占比(%)','滚动60分钟雨峰结束(JST)','选窗前未施加雨量(mm)']
 body='<h1>五场暴雨全过程：道路、人口与措施分析方案</h1><p class="lead">本轮仅完成设计，尚未执行新的时序分析或措施分配。复用五场、两档水位共10组已合格水动力结果，每组109帧；不追加水动力、不训练、不打开封存测试。</p><h2>为什么调整取时</h2><p>现有第4小时快照不足以概括部分事件。7月31日和7月10日前4小时累计雨量不足选定9小时总量的0.01%。因此同时保留完整5分钟过程、降雨参考时刻和道路影响参考时刻，不能把早期共同水位效应解释成整场暴雨相同。</p>'+table(view)+'<h2>三个分析阶段</h2><ol><li><b>道路全过程：</b>统计每个同步时刻的关闭、减速和未知长度；识别关闭/恢复时间括区间、最长采样连续关闭和9小时末尚未恢复的通道。长度裁剪到三区并去重，不把双向车道当两条物理道路，也不把跨界路段全长计入区内。</li><li><b>人口全过程：</b>复用496,345名常住人口与0/10/25m候选接入范围，输出各时刻、峰值和曾受影响住地存量区间。正常支持不足人口单列，不能算成已知暴雨损失。所有人数仍以住地车行可达性为条件。</li><li><b>措施同刻对照：</b>在五场高水位情景选定的代表时刻，比较固定118条道路保护、0/10/20/30%需求移出和UE/SO理想疏导；同一时刻使用相同需求、道路支持和原数值规则。</li></ol><h2>代表时刻如何确定</h2><p><b>降雨参考：</b>最强滚动60分钟雨量窗口的结束时刻，平局取最早；由降雨输入决定。<br><b>道路影响参考：</b>高水位无措施下，三区去重裁剪后的已知关闭道路总长最大时刻，平局取最早；不参考人口或任何措施收益。<br>两个时刻相同则去重，不同则都保留。最多10个代表状态、160个措施格，复用8个正常控制。低/高水位道路与人口在全时序同刻比较，措施首轮聚焦高水位。旧4小时结果保留为明确标注的背景。</p><h2>人数如何避免重复与误读</h2><ul><li>瞬时人数：同一时刻对每个人口区求候选接入点损失的上下端点，再汇总。</li><li>峰值人数：先算每个时刻的三区总量，再找其峰值；不能将每片区各自峰值相加并叫作同时受影响。</li><li>曾受影响：先在每个候选位置上做整个时序的“曾经失联”判断，再求片区区间并只计一次。这是假设居民位置固定的住地存量指标，不是实测出行者去重或受困人数。</li><li>保护收益：从同一个候选位置、同一时刻的配对变化构造；不能用两个总区间的端点直接相减称作保证受益人数。</li></ul><h2>关闭持续时间的分辨率</h2><p>使用实际计算时钟。关闭与恢复发生在相邻5分钟输出之间，只报告括区间；采样关闭占用按梯形积分汇总。不能证明没有短于5分钟的反复通断。起点已关闭和9小时末仍关闭分别标左/右删失，不假定窗口末已恢复。</p><h2>保持固定的条件</h2><p>10m城市几何、0.50m地形来源、关闭/减速0.3/0.1m门槛、原质量掩膜、道路权限/转向/桥隧分层、118条4.743km理想保护、常住人口及楼宇分配区间均保留。未知高程和积水覆盖继续未知，主分析按未知积水道路可用的假设；全未知扣留仅作匹配正常基线的证据压力测试。步道补缺保持行人含义，不转为机动车道路。没有实际管网、排队、车辆服从率或白天在场人口被悄悄补入。</p><h2>输出与指标</h2>'+table(pd.DataFrame(outputs).rename(columns={'metric':'指标','definition':'定义','unit':'单位','interpretation':'解释边界'}))+'<h2>预算和完成条件</h2><p>先用最多8个代表网络状态做接口与计时检查，上限10分钟；全时序阶段活动上限4小时；代表时刻措施阶段活动上限6小时。它们是拟定的停止预算，不是耗时承诺。单任务、内存目标8GiB、新产品上限15GiB，通过离散状态去重避免重复路由和复制大表。措施每次路径180秒、每次优化120秒，候选内间隙≤0.001、原需求账本和车辆守恒规则保持不变。</p><p>完成时应有五场完整轨迹、三区道路时长与未恢复地图、人口瞬时/峰值/曾影响区间、同刻水位影响和措施对照，以及完整复用/缺证据清单。哈希、时钟、裁剪去重、人口守恒或原数值门槛失败即停对应阶段并保留输出，不因措施无效或效果异质而换事件。</p><h2>结论边界</h2><p>这是数值与模型内情景比较，尚无独立实测积水/封路来验证历史准确率。五个日期不是随机事件样本，时刻、水位、措施不能算新独立暴雨。现代城市快照、2020住地人口、干初态9小时和假设河道水位保持一致；没有证明全部交通方式孤立、真实排队延误或工程效果，也不证明城市信息模型必然优于仅地形模型。</p><p>本轮保存独立执行方案，不改已有模拟、人口分配、正式训练划分或旧结果，也不重写AnaSOP的历史代理模型章节。</p><h2>可复核文件</h2><p>'+ ' · '.join('<a href="'+f+'">'+f+'</a>'for f in ['protocol.json','input_inventory.csv','rain_timing_context.csv','metric_dictionary.csv','comparison_matrix.csv','source_bindings.json','validation.json'])+'</p>'
 style='body{font:16px/1.8 system-ui,sans-serif;color:#243647;max-width:1120px;margin:28px auto;padding:0 18px}h1{font-size:28px}h2{margin-top:28px}.lead{padding:16px;background:#e8f2ec}table{display:block;overflow-x:auto;max-width:100%;border-collapse:collapse;font-size:13px}td,th{padding:8px;border:1px solid #dce2e8}th{background:#f0f4f8}li{margin-bottom:8px}'
 (OUT/'review.html').write_text('<!doctype html><html lang="zh"><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>五场暴雨全过程分析方案</title><style>'+style+'</style>'+body+'</html>')
 checks=dict(ten_existing_qualified_cases=len(inventory)==10,five_unique_rain_parents=len({r['parent_id']for r in allruns})==5,all109_actual_frames=all(r['map_frames']==109 for r in inventory),ten_stage_pairs=all({r['stage']for r in inventory if r['event_id']==eid}=={'H','L'}for eid in events),maximum_measure_cells=len(matrix)*16==160,all_sources_present=all((ROOT/n).exists()for n in binding),no_new_hydraulics=True,no_new_routing_or_population_estimation=True,original_results_unchanged=True)
 assert all(checks.values()),checks;dump(OUT/'validation.json',dict(passed=True,checks=checks,source_files_bound=len(binding),hydraulic_cases=10,stored_snapshots=1090,metric_definitions=len(metrics),maximum_future_measure_cells=160,design_only=True,AnaSOP_modified=False));print(json.dumps(dict(plan=str(OUT),validation=checks,source_files=len(binding)),ensure_ascii=False),flush=True)
